#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#define THREADS 256
#define SPLIT 16
__global__ void bn_stats_partial_kernel(
    const float* __restrict__ x,
    double* __restrict__ psum,
    double* __restrict__ psq,
    int N, int C, int H, int W
) {
    const int tid = threadIdx.x;
    const int c = blockIdx.x / SPLIT;
    const int r = blockIdx.x - c * SPLIT;
    const long long HW = 1LL * H * W;
    const bool vec4 = ((HW & 3LL) == 0LL);
    double local_sum = 0.0;
    double local_sumsq = 0.0;
    if (vec4) {
        const long long HW4 = HW >> 2;
        const long long total4 = 1LL * N * HW4;
        const long long begin = (total4 * r) / SPLIT;
        const long long end = (total4 * (r + 1)) / SPLIT;
        for (long long p = begin + tid; p < end; p += THREADS) {
            const long long n = p / HW4;
            const long long v = p - n * HW4;
            const float4* base = reinterpret_cast<const float4*>(x + (n * C + c) * HW);
            const float4 val = base[v];
            local_sum += (double)val.x + (double)val.y + (double)val.z + (double)val.w;
            local_sumsq += (double)val.x * (double)val.x +
                           (double)val.y * (double)val.y +
                           (double)val.z * (double)val.z +
                           (double)val.w * (double)val.w;
        }
    } else {
        const long long total = 1LL * N * HW;
        const long long begin = (total * r) / SPLIT;
        const long long end = (total * (r + 1)) / SPLIT;
        for (long long p = begin + tid; p < end; p += THREADS) {
            const long long n = p / HW;
            const long long s = p - n * HW;
            const long long idx = (n * C + c) * HW + s;
            const float v = x[idx];
            local_sum += (double)v;
            local_sumsq += (double)v * (double)v;
        }
    }
    __shared__ double ssum[THREADS];
    __shared__ double ssumsq[THREADS];
    ssum[tid] = local_sum;
    ssumsq[tid] = local_sumsq;
    __syncthreads();
    for (int stride = THREADS / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            ssum[tid] += ssum[tid + stride];
            ssumsq[tid] += ssumsq[tid + stride];
        }
        __syncthreads();
    }
    if (tid == 0) {
        const int slot = c * SPLIT + r;
        psum[slot] = ssum[0];
        psq[slot] = ssumsq[0];
    }
}
__global__ void bn_finalize_kernel(
    const double* __restrict__ psum,
    const double* __restrict__ psq,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    float* __restrict__ batch_mean,
    float* __restrict__ batch_inv_std,
    long long total,
    float momentum,
    float eps
) {
    const int c = blockIdx.x;
    if (threadIdx.x == 0) {
        double sum = 0.0;
        double sumsq = 0.0;
        const int base = c * SPLIT;
        for (int r = 0; r < SPLIT; ++r) {
            sum += psum[base + r];
            sumsq += psq[base + r];
        }
        const double n = (double)total;
        const double mean = sum / n;
        double var = sumsq / n - mean * mean;
        if (var < 0.0) var = 0.0;
        batch_mean[c] = (float)mean;
        batch_inv_std[c] = rsqrtf((float)var + eps);
        running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * (float)mean;
        if (total > 1) {
            const double unbiased = var * n / (n - 1.0);
            running_var[c] = (1.0f - momentum) * running_var[c] + momentum * (float)unbiased;
        }
    }
}
__global__ void bn_norm_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    const float* __restrict__ batch_mean,
    const float* __restrict__ batch_inv_std,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    int N, int C, int H, int W,
    bool training,
    float eps
) {
    const int tid = threadIdx.x;
    const int c = blockIdx.x / SPLIT;
    const int r = blockIdx.x - c * SPLIT;
    const long long HW = 1LL * H * W;
    const bool vec4 = ((HW & 3LL) == 0LL);
    const float mean = training ? batch_mean[c] : running_mean[c];
    const float inv_std = training ? batch_inv_std[c] : rsqrtf(running_var[c] + eps);
    const float scale = gamma[c] * inv_std;
    const float shift = beta[c] - mean * scale;
    if (vec4) {
        const long long HW4 = HW >> 2;
        const long long total4 = 1LL * N * HW4;
        const long long begin = (total4 * r) / SPLIT;
        const long long end = (total4 * (r + 1)) / SPLIT;
        for (long long p = begin + tid; p < end; p += THREADS) {
            const long long n = p / HW4;
            const long long v = p - n * HW4;
            const long long base_idx = (n * C + c) * HW;
            const float4* in_base = reinterpret_cast<const float4*>(x + base_idx);
            float4* out_base = reinterpret_cast<float4*>(y + base_idx);
            const float4 val = in_base[v];
            float4 out;
            out.x = val.x * scale + shift;
            out.y = val.y * scale + shift;
            out.z = val.z * scale + shift;
            out.w = val.w * scale + shift;
            out_base[v] = out;
        }
    } else {
        const long long total = 1LL * N * HW;
        const long long begin = (total * r) / SPLIT;
        const long long end = (total * (r + 1)) / SPLIT;
        for (long long p = begin + tid; p < end; p += THREADS) {
            const long long n = p / HW;
            const long long s = p - n * HW;
            const long long idx = (n * C + c) * HW + s;
            y[idx] = x[idx] * scale + shift;
        }
    }
}
torch::Tensor bn_forward_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    auto xc = x.contiguous();
    auto g = gamma.contiguous();
    auto b = beta.contiguous();
    auto rm = running_mean.contiguous();
    auto rv = running_var.contiguous();
    auto y = at::empty_like(xc);
    const int N = (int)xc.size(0);
    const int C = (int)xc.size(1);
    const int H = (int)xc.size(2);
    const int W = (int)xc.size(3);
    const long long total = 1LL * N * H * W;
    dim3 grid(C * SPLIT);
    dim3 block(THREADS);
    auto stream = at::cuda::getCurrentCUDAStream();
    if (training) {
        auto dopts = xc.options().dtype(at::kDouble);
        auto psum = at::empty({C, SPLIT}, dopts);
        auto psq = at::empty({C, SPLIT}, dopts);
        auto mean = at::empty({C}, xc.options());
        auto inv = at::empty({C}, xc.options());
        bn_stats_partial_kernel<<<grid, block, 0, stream>>>(
            xc.data_ptr<float>(),
            psum.data_ptr<double>(),
            psq.data_ptr<double>(),
            N, C, H, W
        );
        bn_finalize_kernel<<<dim3(C), dim3(32), 0, stream>>>(
            psum.data_ptr<double>(),
            psq.data_ptr<double>(),
            rm.data_ptr<float>(),
            rv.data_ptr<float>(),
            mean.data_ptr<float>(),
            inv.data_ptr<float>(),
            total,
            (float)momentum,
            (float)eps
        );
        bn_norm_kernel<<<grid, block, 0, stream>>>(
            xc.data_ptr<float>(),
            y.data_ptr<float>(),
            g.data_ptr<float>(),
            b.data_ptr<float>(),
            mean.data_ptr<float>(),
            inv.data_ptr<float>(),
            rm.data_ptr<float>(),
            rv.data_ptr<float>(),
            N, C, H, W,
            true,
            (float)eps
        );
    } else {
        bn_norm_kernel<<<grid, block, 0, stream>>>(
            xc.data_ptr<float>(),
            y.data_ptr<float>(),
            g.data_ptr<float>(),
            b.data_ptr<float>(),
            rm.data_ptr<float>(),
            rv.data_ptr<float>(),
            rm.data_ptr<float>(),
            rv.data_ptr<float>(),
            N, C, H, W,
            false,
            (float)eps
        );
    }
    return y;
}
